"use client";
import React from "react";
import Link from "next/link";

const bottom_nav = () => {
  return (
    <nav className="fixed bottom-0 w-full max-w-md bg-white/95 backdrop-blur-lg border-t border-slate-200 px-4 py-2 flex justify-around items-center z-40">
      <Link
        href="/"
        data-role="switchTab('tab-scan', this)"
        className="nav-btn active flex flex-col items-center gap-1 text-emerald-600"
      >
        <i className="fa-solid fa-wand-magic-sparkles text-lg"></i>
        <span className="text-[10px] font-bold">Prediksi Gizi</span>
      </Link>
      <Link
        href="/akg_dashboard"
        data-role="switchTab('tab-dashboard', this)"
        className="nav-btn flex flex-col items-center gap-1 text-slate-400 hover:text-emerald-600 transition"
      >
        <i className="fa-solid fa-chart-pie text-lg"></i>
        <span className="text-[10px] font-bold">Gizi AKG</span>
      </Link>
      <Link
        href="/report"
        className="flex flex-col items-center gap-1 text-slate-400 hover:text-emerald-600 transition"
      >
        <i className="fa-solid fa-bullhorn text-lg"></i>
        <span className="text-[10px] font-bold">Lapor BGN</span>
      </Link>
      <Link
        href="/quiz"
        data-role="switchTab('tab-edu', this)"
        className="nav-btn flex flex-col items-center gap-1 text-slate-400 hover:text-emerald-600 transition"
      >
        <i className="fa-solid fa-lightbulb text-lg"></i>
        <span className="text-[10px] font-bold">Edu Gizi</span>
      </Link>
    </nav>
  );
};

export default bottom_nav;
